def get_cargo_package_details(name, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0194000" if __import__("os").path.isdir("./environment_mix/0194000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "get-cargo-package-details"

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s[:-1] if s.endswith("Z") else s)
        except Exception:
            return None

    def _mk_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(status, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _mk_id("req"),
            "endpoint": endpoint,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now_iso(),
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = _now_dt()
        per_min = 0
        per_day = 0
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(hours=24)
        for r in logs[-10000:]:
            ts = _parse_dt(r.get("created_at") or r.get("ts") or r.get("timestamp"))
            if not ts:
                continue
            if ts >= minute_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded (120 requests/min).")
        if per_day >= 50000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded (50000 requests/24h).")
        return None

    rl = _enforce_limits()
    if rl:
        _log("error", error_code=rl["error"]["code"])
        return rl

    if not isinstance(name, str) or len(name.strip()) < 1:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`name` must be a non-empty string.")

    # Cargo crate names are lowercase by convention; keep conservative normalization: trim + collapse whitespace
    pkg_key = re.sub(r"\s+", " ", name.strip())
    if pkg_key == "":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`name` must be a non-empty string.")

    ecosystems = _load("ecosystems.json")
    if isinstance(ecosystems, dict) and "rows" in ecosystems:
        ecosystems = ecosystems.get("data", [])
    if not isinstance(ecosystems, list):
        ecosystems = []
    eco = next((e for e in ecosystems if isinstance(e, dict) and e.get("code") == "cargo"), None)
    if not eco:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No available Cargo ecosystem context.")
    eco_id = eco.get("id")

    packages = _load("packages.json")
    if not isinstance(packages, list):
        packages = []

    pkg = next((p for p in packages if isinstance(p, dict) and p.get("ecosystem_id") == eco_id and p.get("package_key") == pkg_key), None)
    if not pkg:
        # Per tool description: NOT_FOUND if unknown to our cache (do not require upstream in offline mode)
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Crate is unknown to registry cache.")

    _log("ok")
    return {"package": pkg}

def search_cargo_packages(query, limit=None, **_extra):
    import json, os, datetime, time, uuid, urllib.parse, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0194000" if __import__("os").path.isdir("./environment_mix/0194000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    endpoint = "search-cargo-packages"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - start) * 1000),
            "created_at": _now()
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        cfg = _load("service_config.json")
        rpm = None
        if isinstance(cfg, dict):
            rpm = cfg.get("rate_limit_per_minute")
        elif isinstance(cfg, list) and cfg and isinstance(cfg[0], dict):
            rpm = cfg[0].get("rate_limit_per_minute")
        if rpm is None:
            rpm = 120
        try:
            rpm = int(rpm)
        except Exception:
            rpm = 120
        if rpm <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=rpm)
        return None

    rl = _rate_limit_check()
    if rl:
        _log("error", error_code=rl["error"]["code"])
        return rl

    if not isinstance(query, str) or len(query.strip()) < 1:
        e = _err("VALIDATION_ERROR", "Parameter `query` is required and must be a non-empty string.")
        _log("error", error_code=e["error"]["code"])
        return e

    if limit is None:
        limit = 10
    # schema says number; accept int-like floats but store int
    try:
        if isinstance(limit, bool):
            raise ValueError()
        limit_i = int(limit)
    except Exception:
        e = _err("VALIDATION_ERROR", "Parameter `limit` must be a number between 1 and 100.")
        _log("error", error_code=e["error"]["code"])
        return e
    if limit_i < 1 or limit_i > 100:
        e = _err("VALIDATION_ERROR", "Parameter `limit` must be between 1 and 100.")
        _log("error", error_code=e["error"]["code"])
        return e

    def _normalize_q(q):
        q = q.strip().lower()
        q = re.sub(r"\s+", " ", q)
        return q

    norm_q = _normalize_q(query)

    ecosystems = _load("ecosystems.json")
    if not isinstance(ecosystems, list):
        ecosystems = []
    cargo = None
    for e in ecosystems:
        if isinstance(e, dict) and e.get("code") == "cargo":
            cargo = e
            break
    if not cargo:
        e = _err("UNAUTHORIZED", "No operational ecosystem configuration available for cargo.")
        _log("error", error_code=e["error"]["code"])
        return e

    if cargo.get("status") not in ("active", "degraded", "disabled"):
        e = _err("UNAUTHORIZED", "No operational ecosystem configuration available for cargo.")
        _log("error", error_code=e["error"]["code"])
        return e

    # supports_search constraint for cargo must be true
    if cargo.get("supports_search") is not True:
        e = _err("CONFLICT", "Cargo ecosystem is not configured to support search.")
        _log("error", error_code=e["error"]["code"])
        return e

    search_queries = _load("search_queries.json")
    if not isinstance(search_queries, list):
        search_queries = []
    search_results = _load("search_results.json")
    if not isinstance(search_results, list):
        search_results = []
    packages = _load("packages.json")
    if not isinstance(packages, list):
        packages = []

    now_dt = datetime.datetime.utcnow()

    def _ttl_seconds_for(ecosystem_row):
        ttl = ecosystem_row.get("cache_ttl_seconds") if isinstance(ecosystem_row, dict) else None
        try:
            ttl = int(ttl)
        except Exception:
            ttl = 300
        if ttl <= 0:
            ttl = 300
        return ttl

    def _is_fresh(sq):
        if sq.get("status") != "fresh":
            return False
        exp = _parse_dt(sq.get("cache_expires_at"))
        return exp is not None and exp >= now_dt

    sq = None
    for row in search_queries:
        if not isinstance(row, dict):
            continue
        if row.get("ecosystem_id") == cargo.get("id") and row.get("normalized_query") == norm_q and row.get("requested_limit") == limit_i:
            sq = row
            break

    def _set_sq_status(new_status):
        nonlocal sq, search_queries
        transitions = {
            "fresh": ["stale", "refreshing", "failed"],
            "stale": ["refreshing", "fresh", "failed"],
            "refreshing": ["fresh", "failed"],
            "failed": ["refreshing", "stale"]
        }
        ts = _now()
        if sq is None:
            sq = {
                "id": "sq_" + uuid.uuid4().hex,
                "ecosystem_id": cargo.get("id"),
                "query": query,
                "normalized_query": norm_q,
                "requested_limit": limit_i,
                "result_count": None,
                "upstream_latency_ms": None,
                "cache_last_fetched_at": None,
                "cache_expires_at": None,
                "status": new_status,
                "created_at": ts,
                "updated_at": ts
            }
            search_queries.append(sq)
        else:
            cur = sq.get("status")
            if cur != new_status:
                allowed = transitions.get(cur, [])
                if new_status not in allowed:
                    return _err("INVALID_TRANSITION", f"Illegal search_query status transition {cur} -> {new_status}.")
            sq["query"] = query
            sq["normalized_query"] = norm_q
            sq["requested_limit"] = limit_i
            sq["status"] = new_status
            sq["updated_at"] = ts
        _save("search_queries.json", search_queries)
        return None

    if sq is not None and _is_fresh(sq):
        # return cached results
        rows = [r for r in search_results if isinstance(r, dict) and r.get("search_query_id") == sq.get("id")]
        rows.sort(key=lambda r: r.get("rank", 10**9))
        out = []
        pkg_by_id = {p.get("id"): p for p in packages if isinstance(p, dict)}
        for r in rows[:limit_i]:
            p = pkg_by_id.get(r.get("package_id"))
            if not p:
                continue
            out.append({
                "rank": r.get("rank"),
                "score": r.get("score"),
                "snippet": r.get("snippet"),
                "package": p
            })
        resp = {
            "query": query,
            "limit": limit_i,
            "total": sq.get("result_count") if isinstance(sq.get("result_count"), int) else len(out),
            "results": out,
            "cache": {"status": sq.get("status"), "last_fetched_at": sq.get("cache_last_fetched_at"), "expires_at": sq.get("cache_expires_at")}
        }
        _log("ok")
        return resp

    # Need refresh
    if cargo.get("status") == "disabled":
        # serve stale cache if present, else fail
        if sq is not None:
            rows = [r for r in search_results if isinstance(r, dict) and r.get("search_query_id") == sq.get("id")]
            rows.sort(key=lambda r: r.get("rank", 10**9))
            pkg_by_id = {p.get("id"): p for p in packages if isinstance(p, dict)}
            out = []
            for r in rows[:limit_i]:
                p = pkg_by_id.get(r.get("package_id"))
                if not p:
                    continue
                out.append({"rank": r.get("rank"), "score": r.get("score"), "snippet": r.get("snippet"), "package": p})
            resp = {
                "query": query,
                "limit": limit_i,
                "total": sq.get("result_count") if isinstance(sq.get("result_count"), int) else len(out),
                "results": out,
                "cache": {"status": sq.get("status"), "last_fetched_at": sq.get("cache_last_fetched_at"), "expires_at": sq.get("cache_expires_at")}
            }
            _log("ok")
            return resp
        e = _err("UPSTREAM_UNAVAILABLE", "Cargo ecosystem is disabled; cannot refresh search and no cache exists.")
        _log("error", error_code=e["error"]["code"])
        return e

    # Transition to refreshing
    t = _set_sq_status("refreshing")
    if t:
        _log("error", error_code=t["error"]["code"])
        return t

    # Offline upstream unavailable: mark failed, retain prior cached results if any
    t2 = _set_sq_status("failed")
    if t2:
        _log("error", error_code=t2["error"]["code"])
        return t2
    # keep existing cache; if none, return upstream unavailable
    rows = []
    if sq is not None:
        rows = [r for r in search_results if isinstance(r, dict) and r.get("search_query_id") == sq.get("id")]
    if not rows:
        e = _err("UPSTREAM_UNAVAILABLE", "Unable to perform upstream Cargo search in offline mode.")
        _log("error", error_code=e["error"]["code"])
        return e

    rows.sort(key=lambda r: r.get("rank", 10**9))
    pkg_by_id = {p.get("id"): p for p in packages if isinstance(p, dict)}
    out = []
    for r in rows[:limit_i]:
        p = pkg_by_id.get(r.get("package_id"))
        if not p:
            continue
        out.append({"rank": r.get("rank"), "score": r.get("score"), "snippet": r.get("snippet"), "package": p})

    resp = {
        "query": query,
        "limit": limit_i,
        "total": sq.get("result_count") if isinstance(sq.get("result_count"), int) else len(out),
        "results": out,
        "cache": {"status": sq.get("status"), "last_fetched_at": sq.get("cache_last_fetched_at"), "expires_at": sq.get("cache_expires_at")}
    }
    _log("ok")
    return resp

def list_cargo_package_versions(name, limit=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0194000" if __import__("os").path.isdir("./environment_mix/0194000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    endpoint = "list-cargo-package-versions"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - start) * 1000),
            "created_at": _now()
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        cfg = _load("service_config.json")
        rpm = None
        if isinstance(cfg, dict):
            rpm = cfg.get("rate_limit_per_minute")
        elif isinstance(cfg, list) and cfg and isinstance(cfg[0], dict):
            rpm = cfg[0].get("rate_limit_per_minute")
        if rpm is None:
            rpm = 120
        try:
            rpm = int(rpm)
        except Exception:
            rpm = 120
        if rpm <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=rpm)
        return None

    rl = _rate_limit_check()
    if rl:
        _log("error", error_code=rl["error"]["code"])
        return rl

    if not isinstance(name, str) or len(name.strip()) < 1:
        e = _err("VALIDATION_ERROR", "Parameter `name` is required and must be a non-empty string.")
        _log("error", error_code=e["error"]["code"])
        return e

    if limit is None:
        limit = 100
    try:
        if isinstance(limit, bool):
            raise ValueError()
        limit_i = int(limit)
    except Exception:
        e = _err("VALIDATION_ERROR", "Parameter `limit` must be a number between 1 and 1000.")
        _log("error", error_code=e["error"]["code"])
        return e
    if limit_i < 1 or limit_i > 1000:
        e = _err("VALIDATION_ERROR", "Parameter `limit` must be between 1 and 1000.")
        _log("error", error_code=e["error"]["code"])
        return e

    crate_key = name.strip()

    ecosystems = _load("ecosystems.json")
    if not isinstance(ecosystems, list):
        ecosystems = []
    cargo = None
    for e in ecosystems:
        if isinstance(e, dict) and e.get("code") == "cargo":
            cargo = e
            break
    if not cargo:
        e = _err("UNAUTHORIZED", "No operational ecosystem configuration available for cargo.")
        _log("error", error_code=e["error"]["code"])
        return e

    packages = _load("packages.json")
    if not isinstance(packages, list):
        packages = []
    pkg = None
    for p in packages:
        if isinstance(p, dict) and p.get("ecosystem_id") == cargo.get("id") and p.get("package_key") == crate_key:
            pkg = p
            break
    if not pkg or pkg.get("status") == "not_found":
        e = _err("NOT_FOUND", "Package not found in registry cache.")
        _log("error", error_code=e["error"]["code"])
        return e

    now_dt = datetime.datetime.utcnow()
    exp = _parse_dt(pkg.get("cache_expires_at"))
    stale = exp is None or exp < now_dt

    # Refresh if stale and ecosystem not disabled, when possible (offline -> cannot).
    if stale and cargo.get("status") != "disabled":
        # If we have versions already, serve them; else upstream unavailable.
        versions = _load("package_versions.json")
        if not isinstance(versions, list):
            versions = []
        has_any = any(isinstance(v, dict) and v.get("package_id") == pkg.get("id") for v in versions)
        if not has_any:
            e = _err("UPSTREAM_UNAVAILABLE", "Package versions are stale and cannot be refreshed in offline mode.")
            _log("error", error_code=e["error"]["code"])
            return e

    versions = _load("package_versions.json")
    if not isinstance(versions, list):
        versions = []

    rows = [v for v in versions if isinstance(v, dict) and v.get("package_id") == pkg.get("id")]

    def _sort_key(v):
        dt = _parse_dt(v.get("published_at"))
        # published_at desc NULLS LAST; then version desc
        null_flag = 1 if dt is None else 0
        ts = dt.timestamp() if dt else 0.0
        ver = v.get("version") or ""
        return (null_flag, -ts, ver)

    # We need published_at desc; our key makes NULLS LAST and ts descending by -ts.
    rows.sort(key=_sort_key)
    out = rows[:limit_i]

    resp = {
        "package": pkg,
        "limit": limit_i,
        "total": len(rows),
        "versions": out
    }
    _log("ok")
    return resp

def get_golang_package_details(module, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0194000" if __import__("os").path.isdir("./environment_mix/0194000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-golang-package-details"

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s.replace(tzinfo=None)
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s[:-1] if s.endswith("Z") else s).replace(tzinfo=None)
        except Exception:
            return None

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log(status, error_code=None):
        logs = _ensure_list(_load("request_logs.json"))
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "endpoint": endpoint,
                "credential_id": None,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_iso(),
            }
        )
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _ensure_list(_load("request_logs.json"))
        now = _now_dt()
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(hours=24)
        per_min = 0
        per_day = 0
        for r in logs[-20000:]:
            ts = _parse_dt(r.get("created_at") or r.get("timestamp") or r.get("ts"))
            if not ts:
                continue
            if ts >= minute_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded (120 requests/min).")
        if per_day >= 50000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded (50,000 requests/day).")
        return None

    def _normalize_module(m):
        return m.strip()

    def _find_ecosystem(code):
        ecos = _ensure_list(_load("ecosystems.json"))
        for e in ecos:
            if e.get("code") == code:
                return e
        return None

    try:
        if not isinstance(module, str) or len(module.strip()) < 1:
            rl = _rate_limit_check()
            if rl:
                _log("error", rl["error"]["code"])
                return rl
            out = _err("VALIDATION_ERROR", "`module` must be a non-empty string.")
            _log("error", out["error"]["code"])
            return out

        rl = _rate_limit_check()
        if rl:
            _log("error", rl["error"]["code"])
            return rl

        eco = _find_ecosystem("golang")
        if not eco:
