def search_nuget_packages(query, limit=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0194000" if __import__("os").path.isdir("./environment_mix/0194000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "search-nuget-packages"

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s[:-1] if s.endswith("Z") else s)
        except Exception:
            return None

    def _mk_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(status, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _mk_id("req"),
            "endpoint": endpoint,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now_iso(),
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = _now_dt()
        per_min = 0
        per_day = 0
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(hours=24)
        for r in logs[-10000:]:
            ts = _parse_dt(r.get("created_at") or r.get("ts") or r.get("timestamp"))
            if not ts:
                continue
            if ts >= minute_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded (120 requests/min).")
        if per_day >= 50000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded (50000 requests/24h).")
        return None

    rl = _enforce_limits()
    if rl:
        _log("error", error_code=rl["error"]["code"])
        return rl

    if not isinstance(query, str) or len(query.strip()) < 1:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`query` must be a non-empty string.")
    if limit is None:
        limit = 10
    if isinstance(limit, bool) or not isinstance(limit, (int, float)):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`limit` must be a number between 1 and 100.")
    limit_i = int(limit)
    if limit_i < 1 or limit_i > 100:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`limit` must be between 1 and 100.")

    normalized_query = re.sub(r"\s+", " ", query.strip().lower())

    ecosystems = _load("ecosystems.json")
    if isinstance(ecosystems, dict) and "rows" in ecosystems:
        ecosystems = ecosystems.get("data", [])
    if not isinstance(ecosystems, list):
        ecosystems = []
    eco = next((e for e in ecosystems if isinstance(e, dict) and e.get("code") == "nuget"), None)
    if not eco:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No available NuGet ecosystem context.")
    eco_id = eco.get("id")

    sqs = _load("search_queries.json")
    if not isinstance(sqs, list):
        sqs = []
    srs = _load("search_results.json")
    if not isinstance(srs, list):
        srs = []
    pkgs = _load("packages.json")
    if not isinstance(pkgs, list):
        pkgs = []

    sq = next(
        (r for r in sqs
         if isinstance(r, dict)
         and r.get("ecosystem_id") == eco_id
         and r.get("normalized_query") == normalized_query
         and r.get("requested_limit") == limit_i),
        None
    )

    results = []
    cache_state = "miss"
    if sq:
        cache_state = sq.get("status") or "unknown"
        sq_id = sq.get("id")
        rows = [r for r in srs if isinstance(r, dict) and r.get("search_query_id") == sq_id]
        rows.sort(key=lambda r: (r.get("rank") if isinstance(r.get("rank"), int) else 10**9))
        rows = rows[:limit_i]
        pkg_by_id = {p.get("id"): p for p in pkgs if isinstance(p, dict) and p.get("id")}
        for r in rows:
            p = pkg_by_id.get(r.get("package_id"))
            if p:
                results.append({"package": p, "rank": r.get("rank"), "score": r.get("score"), "snippet": r.get("snippet")})

    _log("ok")
    return {
        "query": query,
        "normalized_query": normalized_query,
        "limit": limit_i,
        "results": results,
        "count": len(results),
        "cache": {"state": cache_state, "search_query_id": (sq.get("id") if sq else None)},
    }

